export const allTemplates = (): readonly InterleavedTemplate[] => INTERLEAVED_TEMPLATES;
export const templatesFor = (required: RequiredReserve): readonly InterleavedTemplate[] => INTERLEAVED_TEMPLATES.filter(template=>template.required===required);
export const templateById = (id:string): InterleavedTemplate | undefined => INTERLEAVED_TEMPLATES.find(template=>template.id===id);
export function columnsForTemplate(template:InterleavedTemplate):Tile[][] {
  const used=Array<number>(9).fill(0),heights=[10,11,11,11,11,11,11,11,11,10];
  if(template.columns.length!==10)throw new Error('Template requires ten columns');
  const columns=template.columns.map((column,c)=>{
    if(column.length!==heights[c])throw new Error('Template height mismatch');
    return [...column].map((value,index)=>{
      const kind=Number(value) as TileKind;
      if(!Number.isInteger(kind)||kind<0||kind>8)throw new Error('Invalid template kind');
      return {id:kind*12+used[kind]!++,kind,open:index===0};
    });
  });
  if(used.some(count=>count!==12))throw new Error('Invalid template inventory');
  return columns;
}
export function solutionForTemplate(template:InterleavedTemplate):Move[] {
  const location=(index:number):{zone:'column'|'reserve';index:number}=>index<10?{zone:'column',index}:{zone:'reserve',index:index-10};
  return template.solution.map(action=>({type:'move',from:location(action[1]),to:location(action[2]),count:action[3]}));
}
